INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10301, 'ក្នុងចំណោមអំណះអំណាងខាងក្រោម តើមួយណាជាសំណើ (Proposition)?', NULL, '["«សុភីមានមាឌតូច»", "«ថ្ងៃស្អែកនឹងមានភ្លៀងធ្លាក់ខ្លាំងនៅភ្នំពេញ»", "«5 ជាចំនួនបឋម»", "«តើអ្នកសុខសប្បាយទេ?»"]', 2, NULL, 1, 'mcq', 'សំណើគឺជាអំណះអំណាងដែលគេអាចសម្រេចបានច្បាស់លាស់ថាពិត ឬមិនពិត។', 'តក្កវិទ្យា', 'easy', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10302, 'តើសំណើ \(p : \text{«} 2\,024 \text{ ជាចំនួនគត់គូ»}\) មានតម្លៃភាពពិតស្មើនឹងប៉ុន្មាន?', NULL, '["\\(2\\)", "មិនអាចកំណត់បាន", "\\(0\\)", "\\(1\\)"]', 3, NULL, 1, 'mcq', 'ដោយ 2024 ចែកដាច់នឹង 2 នោះវាជាចំនួនគត់គូ (ពិត) នាំឱ្យ \(\text{ត.}(p) = 1\)។', 'តក្កវិទ្យា', 'easy', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10303, 'សំណើឈ្នាប់និង \(p \wedge q\) ពិតតែក្នុងករណីណា?', NULL, '["សំណើ \\(p\\) និង \\(q\\) ពិតទាំងពីរ", "សំណើ \\(p\\) ពិតតែមួយគត់", "យ៉ាងហោចសំណើមួយពិត", "សំណើ \\(p\\) និង \\(q\\) មិនពិតទាំងពីរ"]', 0, NULL, 1, 'mcq', 'តាមតារាងភាពពិត សំណើ \(p \wedge q\) មានតម្លៃភាពពិតស្មើ 1 លុះត្រាតែ \(p\) ពិត និង \(q\) ពិត។', 'តក្កវិទ្យា', 'easy', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10304, 'សំណើឈ្នាប់ឬ \(p \vee q\) មិនពិតតែក្នុងករណីណា?', NULL, '["សំណើ \\(p\\) ពិត និង \\(q\\) មិនពិត", "សំណើ \\(p\\) និង \\(q\\) មិនពិតទាំងពីរ", "សំណើ \\(p\\) និង \\(q\\) ពិតទាំងពីរ", "សំណើ \\(p\\) មិនពិត និង \\(q\\) ពិត"]', 1, NULL, 1, 'mcq', 'សំណើ \(p \vee q\) មិនពិត (ស្មើ 0) តែក្នុងករណី \(p=0\) និង \(q=0\) ទាំងពីរព្រមគ្នា។', 'តក្កវិទ្យា', 'easy', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10305, 'បើសំណើ \(p\) ពិត (\(\text{ត.}(p) = 1\)) នោះតម្លៃភាពពិតនៃសំណើបដិសេធ \(\bar{p}\) គឺ៖', NULL, '["\\(-1\\)", "\\(0.5\\)", "\\(0\\)", "\\(1\\)"]', 2, NULL, 1, 'mcq', 'សំណើបដិសេធមានតម្លៃភាពពិតផ្ទុយពីសំណើដើមជានិច្ច ដូច្នេះ \(\text{ត.}(\bar{p}) = 0\)។', 'តក្កវិទ្យា', 'easy', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10306, 'ក្នុងសំណើលក្ខខណ្ឌ \(p \Rightarrow q\) តើសំណើ \(p\) ហៅថាអ្វី?', NULL, '["សំណើច្រាស", "សំណើផ្ទុយ", "បុព្វសំណើ (ឬសម្មតិកម្ម)", "វិបាក (ឬសេចក្តីសន្និដ្ឋាន)"]', 2, NULL, 1, 'mcq', 'ក្នុង \(p \Rightarrow q\) សំណើ \(p\) ជាបុព្វសំណើ ហើយ \(q\) ជាវិបាក។', 'តក្កវិទ្យា', 'easy', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10307, 'តើសំណើណាជាសំណើផ្ទុយពីសម្មតិកម្ម (Contrapositive) នៃសំណើ \(p \Rightarrow q\)?', NULL, '["\\(\\bar{p} \\Rightarrow \\bar{q}\\)", "\\(q \\Rightarrow p\\)", "\\(\\bar{q} \\Rightarrow \\bar{p}\\)", "\\(\\bar{p} \\Rightarrow q\\)"]', 2, NULL, 1, 'mcq', 'សំណើផ្ទុយពីសម្មតិកម្មនៃ \(p \Rightarrow q\) គឺ \(\bar{q} \Rightarrow \bar{p}\)។', 'តក្កវិទ្យា', 'easy', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10308, 'សំណើឈ្នាប់សមមូល \(p \Leftrightarrow q\) ត្រូវបានកំណត់ដោយ៖', NULL, '["\\((p \\Rightarrow q) \\vee (q \\Rightarrow p)\\)", "\\((p \\Rightarrow q) \\wedge (q \\Rightarrow p)\\)", "\\(p \\wedge q\\)", "\\((\\bar{p} \\Rightarrow \\bar{q}) \\wedge (p \\Rightarrow q)\\)"]', 1, NULL, 1, 'mcq', 'តាមនិយមន័យ \(p \Leftrightarrow q = (p \Rightarrow q) \wedge (q \Rightarrow p)\)។', 'តក្កវិទ្យា', 'easy', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10309, 'ដើម្បីបង្ហាញថាអំណះអំណាងមួយ «មិនពិត» គេគ្រាន់តែរកឃើញ៖', NULL, '["បង្ហាញថាសំណើច្រាសពិត", "ឧទាហរណ៍ផ្ទញ់តែមួយគត់ (Counterexample)", "ស្រាយបញ្ជាក់តាមសំណើផ្ទុយពីការពិត", "បង្ហាញគ្រប់ករណីទាំងអស់មិនពិត"]', 1, NULL, 1, 'mcq', 'ឧទាហរណ៍ផ្ទញ់តែមួយគត់គឺគ្រប់គ្រាន់ដើម្បីបញ្ជាក់ថាអំណះអំណាងមួយមិនពិត។', 'តក្កវិទ្យា', 'easy', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10310, 'សំណើបដិសេធពីរដង \(\bar{\bar{p}}\) សមមូលនឹងសំណើណា?', NULL, '["\\(p \\vee \\bar{p}\\)", "\\(\\bar{p}\\)", "\\(p \\wedge \\bar{p}\\)", "\\(p\\)"]', 3, NULL, 1, 'mcq', 'បដិសេធនៃបដិសេធ គឺជាសំណើដើម \(\bar{\bar{p}} = p\)។', 'តក្កវិទ្យា', 'easy', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10311, 'គេមានសំណើ \(p : \text{«} 7 \text{ ជាតួចែកនៃ } 15 \text{»}\) និង \(q : \text{«} 7 \text{ ជាចំនួនបឋម»}\)។ តម្លៃភាពពិតនៃ \(p \wedge q\) គឺ៖', NULL, '["មិនអាចសន្និដ្ឋានបាន", "\\(1\\)", "\\(-1\\)", "\\(0\\)"]', 3, NULL, 2, 'mcq', 'ដោយ \(\text{ត.}(p) = 0\) និង \(\text{ត.}(q) = 1\) នាំឱ្យ \(\text{ត.}(p \wedge q) = 0 \wedge 1 = 0\)។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10312, 'គេមាន \(r : \text{«} 2\,021 \text{ ចែកដាច់នឹង } 3 \text{»}\) និង \(s : \text{«} 2\,024 \text{ ជាចំនួនគត់គូ»}\)។ តម្លៃភាពពិតនៃ \(r \vee s\) គឺ៖', NULL, '["\\(2\\)", "មិនអាចកំណត់បាន", "\\(0\\)", "\\(1\\)"]', 3, NULL, 2, 'mcq', 'ដោយ \(\text{ត.}(r) = 0\) និង \(\text{ត.}(s) = 1\) នាំឱ្យ \(\text{ត.}(r \vee s) = 0 \vee 1 = 1\)។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10313, 'តាមលក្ខណៈដឺម៉កហ្កង់ (De Morgan) សំណើបដិសេធ \(\overline{p \wedge q}\) គឺសមមូលនឹង៖', NULL, '["\\(\\bar{p} \\wedge \\bar{q}\\)", "\\(\\overline{p \\vee q}\\)", "\\(\\bar{p} \\vee \\bar{q}\\)", "\\(p \\vee q\\)"]', 2, NULL, 2, 'mcq', 'ច្បាប់ដឺម៉កហ្កង់៖ \(\overline{p \wedge q} = \bar{p} \vee \bar{q}\)។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10314, 'សំណើលក្ខខណ្ឌ \(p \Rightarrow q\) មិនពិត (ស្មើ 0) តែក្នុងករណីណា?', NULL, '["\\(p\\) ពិត ហើយ \\(q\\) ពិត", "\\(p\\) ពិត ហើយ \\(q\\) មិនពិត", "\\(p\\) មិនពិត ហើយ \\(q\\) មិនពិត", "\\(p\\) មិនពិត ហើយ \\(q\\) ពិត"]', 1, NULL, 2, 'mcq', '\(1 \Rightarrow 0\) ស្មើនឹង 0 ក្រៅពីនេះ \(p \Rightarrow q\) ពិតជានិច្ច។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10315, 'បើសំណើ \(p \Rightarrow q\) ជាសំណើពិត នោះសំណើផ្ទុយពីសម្មតិកម្ម \(\bar{q} \Rightarrow \bar{p}\) គឺជា៖', NULL, '["សំណើមិនពិតជានិច្ច", "សំណើពិតលុះត្រាតែ q ពិត", "សំណើពិតជានិច្ច", "មិនអាចកំណត់បាន"]', 2, NULL, 2, 'mcq', 'សំណើដើម និងសំណើផ្ទុយពីសម្មតិកម្មមានតម្លៃភាពពិតដូចគ្នាជានិច្ច។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10316, 'បើ \(p\) ពិត ហើយ \(q\) មិនពិត នោះតម្លៃភាពពិតនៃ \(\bar{p} \vee q\) គឺ៖', NULL, '["មិនអាចកំណត់បាន", "\\(0\\)", "\\(2\\)", "\\(1\\)"]', 1, NULL, 2, 'mcq', 'ដោយ \(p=1 \implies \bar{p}=0\) នាំឱ្យ \(\bar{p} \vee q = 0 \vee 0 = 0\)។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10317, 'តម្លៃភាពពិតនៃសំណើ \((x^2 - 4 = 0) \Leftrightarrow (x = 2 \text{ ឬ } x = -2)\) ចំពោះ \(x \in \mathbb{R}\) គឺ៖', NULL, '["គ្មានន័យ", "\\(0\\) (ជាសំណើមិនពិត)", "\\(1\\) (ជាសំណើពិត)", "មិនមែនជាសំណើ"]', 2, NULL, 2, 'mcq', 'សំណើទាំងពីរផ្ទៀងផ្ទាត់សមមូលគ្នាទាំងស្រុង នាំឱ្យតម្លៃភាពពិតស្មើ 1។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10318, 'ក្នុងសម្រាយបញ្ជាក់ដោយផ្ទាល់ដើម្បីបង្ហាញថា «ផលបូកពីរចំនួនគត់សេសជាចំនួនគត់គូ» តើគេត្រូវតាងចំនួនគត់សេស \(x, y\) យ៉ាងដូចម្តេច?', NULL, '["\\(x = 2n, \\; y = 2m\\)", "\\(x = 2n-1, \\; y = 2n+1\\)", "\\(x = n+1, \\; y = m+1\\)", "\\(x = 2n+1, \\; y = 2m+1\\) (\\(n, m \\in \\mathbb{Z}\\))"]', 3, NULL, 2, 'mcq', 'ចំនួនគត់សេសមានទម្រង់ \(2k+1\) ដែល \(k \in \mathbb{Z}\)។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10319, 'សំណើផ្ទុយពីសម្មតិកម្មនៃ «បើ \(n^2\) ជាចំនួនគត់គូ នោះ \(n\) ជាចំនួនគត់គូ» គឺ៖', NULL, '["បើ \\(n^2\\) ជាចំនួនគត់សេស នោះ \\(n\\) ជាចំនួនគត់សេស", "បើ \\(n\\) ជាចំនួនគត់សេស នោះ \\(n^2\\) ជាចំនួនគត់គូ", "បើ \\(n\\) ជាចំនួនគត់គូ នោះ \\(n^2\\) ជាចំនួនគត់គូ", "បើ \\(n\\) ជាចំនួនគត់សេស នោះ \\(n^2\\) ជាចំនួនគត់សេស"]', 3, NULL, 2, 'mcq', 'បដិសេធវិបាក \(\bar{q}\) នាំឱ្យបដិសេធបុព្វសំណើ \(\bar{p}\)។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10320, 'ក្នុងសម្រាយបញ្ជាក់តាមសំណើផ្ទុយពីការពិតដើម្បីបង្ហាញថា \(\sqrt{2}\) ជាចំនួនអសនិទាន តើជំហានដំបូងគេត្រូវធ្វើអ្វី?', NULL, '["ឧបមាថា \\(\\sqrt{2}\\) មិនមែនជាចំនួនពិត", "ឧបមាថា \\(\\sqrt{2}\\) ជាចំនួនសនិទាន", "ឧបមាថា \\(2\\) ជាចំនួនអសនិទាន", "ឧបមាថា \\(\\sqrt{2} = 0\\)"]', 1, NULL, 2, 'mcq', 'វិធីផ្ទុយពីការពិតតម្រូវឱ្យឧបមាថាសំណើបដិសេធពិត (គឺ \(\sqrt{2}\) ជាចំនួនសនិទាន)។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10321, 'តើតម្លៃណាជាឧទាហរណ៍ផ្ទញ់នៃអំណះអំណាង «គ្រប់ចំនួនបឋមសុទ្ធតែជាចំនួនសេស»?', NULL, '["\\(2\\)", "\\(9\\)", "\\(3\\)", "\\(1\\)"]', 0, NULL, 2, 'mcq', '2 ជាចំនួនបឋម តែជាចំនួនគត់គូ ដូច្នេះវាជាឧទាហរណ៍ផ្ទញ់។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10322, 'សំណើបដិសេធនៃ «សិស្សខិតខំរៀន និងប្រឡងជាប់» គឺ៖', NULL, '["សិស្សប្រឡងជាប់ ឬមិនខិតខំរៀន", "សិស្សខិតខំរៀន តែមិនប្រឡងជាប់", "សិស្សមិនខិតខំរៀន ឬមិនប្រឡងជាប់", "សិស្សមិនខិតខំរៀន និងមិនប្រឡងជាប់"]', 2, NULL, 2, 'mcq', 'តាមច្បាប់ដឺម៉កហ្កង់ បដិសេធនៃឈ្នាប់ «និង» គឺឈ្នាប់ «ឬ» នៃបដិសេធនីមួយៗ។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10323, 'បើ \(p\) មិនពិត ហើយ \(q\) ពិត នោះតម្លៃភាពពិតនៃ \(p \Rightarrow q\) គឺ៖', NULL, '["\\(-1\\)", "មិនអាចកំណត់បាន", "\\(1\\)", "\\(0\\)"]', 2, NULL, 2, 'mcq', '\(0 \Rightarrow 1\) គឺជាសំណើពិត (\(1\))។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10324, 'តើគូតម្លៃ \((a, b)\) ណាជាឧទាហរណ៍ផ្ទញ់នៃសំណើ «បើ \(a > b\) នោះ \(a^2 > b^2\) ចំពោះគ្រប់ចំនួនពិត»?', NULL, '["\\(a = 4, \\; b = 0\\)", "\\(a = 5, \\; b = 2\\)", "\\(a = 3, \\; b = 1\\)", "\\(a = 1, \\; b = -3\\)"]', 3, NULL, 2, 'mcq', 'យក \(a=1, b=-3\) គេបាន \(1 > -3\) ប៉ុន្តែ \(1^2 = 1 < (-3)^2 = 9\) (ផ្ទញ់)។', 'តក្កវិទ្យា', 'medium', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10325, 'បើ \(p\) មិនពិត, \(q\) មិនពិត និង \(r\) ពិត។ រកតម្លៃភាពពិតនៃកន្សោមសំណើ \((p \wedge \bar{q}) \vee (\bar{p} \wedge r)\)៖', NULL, '["មិនអាចកំណត់បាន", "\\(2\\)", "\\(1\\)", "\\(0\\)"]', 2, NULL, 3, 'mcq', '\(p \wedge \bar{q} = 0 \wedge 1 = 0\) និង \(\bar{p} \wedge r = 1 \wedge 1 = 1\) នាំឱ្យ \(0 \vee 1 = 1\)។', 'តក្កវិទ្យា', 'hard', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10326, 'ក្នុងចំណោមកន្សោមសំណើខាងក្រោម តើកន្សោមណាជាតូតូឡូស៊ី (Tautology - ពិតជានិច្ច)?', NULL, '["\\(p \\vee \\bar{p}\\)", "\\(p \\Rightarrow \\bar{p}\\)", "\\(p \\wedge \\bar{p}\\)", "\\(\\bar{p} \\Leftrightarrow p\\)"]', 0, NULL, 3, 'mcq', '\(p \vee \bar{p}\) តែងតែមានតម្លៃភាពពិតស្មើ 1 ជានិច្ច មិនថា p ពិត ឬមិនពិត។', 'តក្កវិទ្យា', 'hard', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10327, 'សំណើលក្ខខណ្ឌ \(p \Rightarrow q\) សមមូលគ្នានឹងកន្សោមតក្កវិទ្យាណាខាងក្រោម?', NULL, '["\\(\\bar{p} \\vee q\\)", "\\(\\bar{q} \\Rightarrow p\\)", "\\(p \\vee \\bar{q}\\)", "\\(\\bar{p} \\wedge q\\)"]', 0, NULL, 3, 'mcq', 'តារាងភាពពិតនៃ \(p \Rightarrow q\) និង \(\bar{p} \vee q\) មានតម្លៃ [1, 0, 1, 1] ដូចគ្នាគ្រប់ករណី។', 'តក្កវិទ្យា', 'hard', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10328, 'ក្នុងសម្រាយបញ្ជាក់តាមសំណើផ្ទុយពីការពិតដែលបង្ហាញថា \(\sqrt[4]{2}\) ជាចំនួនអសនិទាន ដោយតាង \(\sqrt[4]{2} = \frac{a}{b}\) (\(\text{GCD}(a,b)=1\)) គេទាញបាន \(a^4 = 2b^4\)។ តើការទាញសេចក្តីសន្និដ្ឋានណាដែលនាំទៅរកភាពមិនពិត?', NULL, '["\\(a\\) ជាចំនួនគូ និង \\(b\\) ជាចំនួនគូ នាំឱ្យ \\(\\text{GCD}(a,b) \\ge 2\\)", "\\(a\\) ជាចំនួនសេស និង \\(b\\) ជាចំនួនគូ", "\\(a^4\\) មិនមែនជាចំនួនគត់", "\\(a\\) ជាចំនួនគូ និង \\(b\\) ជាចំនួនសេស"]', 0, NULL, 3, 'mcq', 'ការដែល a និង b សុទ្ធតែជាចំនួនគូ នាំឱ្យមានតួចែករួមយ៉ាងតិច 2 ផ្ទុយពីការសន្មតថា GCD=1។', 'តក្កវិទ្យា', 'hard', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10329, 'ដើម្បីស្រាយបញ្ជាក់តាមសំណើផ្ទុយពីសម្មតិកម្មនូវសំណើ «បើ \(mn\) មិនមែនជាពហុគុណនៃ 3 នោះ \(m\) និង \(n\) មិនមែនជាពហុគុណនៃ 3» តើសំណើផ្ទុយពីសម្មតិកម្មត្រូវសរសេរយ៉ាងដូចម្តេច?', NULL, '["បើ \\(mn\\) ជាពហុគុណនៃ 3 នោះ \\(m\\) ជាពហុគុណនៃ 3", "បើ \\(m\\) ជាពហុគុណនៃ 3 និង \\(n\\) ជាពហុគុណនៃ 3 នោះ \\(mn\\) មិនមែនជាពហុគុណនៃ 3", "បើ \\(m\\) មិនមែនជាពហុគុណនៃ 3 នោះ \\(mn\\) ជាពហុគុណនៃ 3", "បើ \\(m\\) ជាពហុគុណនៃ 3 ឬ \\(n\\) ជាពហុគុណនៃ 3 នោះ \\(mn\\) ជាពហុគុណនៃ 3"]', 3, NULL, 3, 'mcq', 'បដិសេធនៃ «m មិនមែន... និង n មិនមែន...» គឺ «m ជា... ឬ n ជា...» តាមច្បាប់ដឺម៉កហ្កង់។', 'តក្កវិទ្យា', 'hard', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10330, 'តើគូចំនួនអសនិទានណាខ្លះដែលជាឧទាហរណ៍ផ្ទញ់បញ្ជាក់ថា «ផលគុណនៃពីរចំនួនអសនិទានខុសគ្នា មិនប្រាកដជាចំនួនអសនិទានឡើយ»?', NULL, '["\\(\\pi\\) និង \\(\\sqrt{2}\\)", "\\(\\sqrt{2}\\) និង \\(\\sqrt{8}\\)", "\\(\\sqrt{3}\\) និង \\(\\sqrt{5}\\)", "\\(\\sqrt{2}\\) និង \\(\\sqrt{3}\\)"]', 1, NULL, 3, 'mcq', '\(\sqrt{2} \times \sqrt{8} = \sqrt{16} = 4\) ដែល 4 ជាចំនួនសនិទាន។', 'តក្កវិទ្យា', 'hard', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10331, 'សំណើផ្ទុយពីសម្មតិកម្មនៃ «បើ \(x^2 - 1 < 0\) នោះ \(-1 < x < 1\)» គឺ៖', NULL, '["បើ \\(x \\ge 1\\) នោះ \\(x^2 - 1 < 0\\)", "បើ \\(x \\le -1\\) ឬ \\(x \\ge 1\\) នោះ \\(x^2 - 1 \\ge 0\\)", "បើ \\(-1 \\le x \\le 1\\) នោះ \\(x^2 - 1 \\ge 0\\)", "បើ \\(x < -1\\) ឬ \\(x > 1\\) នោះ \\(x^2 - 1 > 0\\)"]', 1, NULL, 3, 'mcq', 'បដិសេធនៃ \(-1 < x < 1\) គឺ \(x \le -1 \vee x \ge 1\) ហើយបដិសេធនៃ \(x^2-1 < 0\) គឺ \(x^2-1 \ge 0\)។', 'តក្កវិទ្យា', 'hard', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10332, 'ប្រព័ន្ធភ្លើងស្តុបឆ្លាតវៃមួយមានសេនស័រ \(p\) (មានរថយន្តលើផ្លូវ A) និង \(q\) (មានរថយន្តលើផ្លូវ B)។ ភ្លើងខៀវផ្លូវ A នឹងបើកកាលណា \(p \wedge \bar{q}\) ពិត។ តើភ្លើងខៀវផ្លូវ A បើកក្នុងលក្ខខណ្ឌណា?', NULL, '["គ្មានរថយន្តនៅលើផ្លូវទាំងពីរ", "គ្មានរថយន្តនៅលើផ្លូវ A", "មានរថយន្តនៅលើផ្លូវទាំងពីរ", "មានរថយន្តនៅលើផ្លូវ A និងគ្មានរថយន្តនៅលើផ្លូវ B"]', 3, NULL, 3, 'mcq', '\(p \wedge \bar{q} = 1\) លុះត្រាតែ \(p=1\) (មានរថយន្តលើផ្លូវ A) និង \(q=0\) (គ្មានរថយន្តលើផ្លូវ B)។', 'តក្កវិទ្យា', 'pisa', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10333, 'ប្រព័ន្ធប្រកាសអាសន្នឃ្លាំងមួយរោទិ៍កាលណាមានចលនា (\(M\)) ឬកញ្ចក់បង្អួចបែក (\(G\)) គឺ \(\text{Alarm} = M \vee G\)។ ប្រសិនបើប្រព័ន្ធមិនរោទិ៍ (\(\overline{M \vee G}\)) តើតាមច្បាប់ De Morgan គេអាចសន្និដ្ឋានយ៉ាងដូចម្តេច?', NULL, '["គ្មានចលនា និងកញ្ចក់បង្អួចមិនបែក (\\(\\bar{M} \\wedge \\bar{G}\\))", "គ្មានចលនា ឬកញ្ចក់បង្អួចមិនបែក", "កញ្ចក់បង្អួចបែក តែគ្មានចលនា", "មានចលនា តែបង្អួចមិនបែក"]', 0, NULL, 3, 'mcq', 'តាមច្បាប់ដឺម៉កហ្កង់ \(\overline{M \vee G} = \bar{M} \wedge \bar{G}\) មានន័យថាគ្មានចលនា និងបង្អួចមិនបែក។', 'តក្កវិទ្យា', 'pisa', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10334, 'លក្ខខណ្ឌធានាឧបករណ៍អេឡិចត្រូនិកចែងថា៖ «បើអ្នកបកតែមបិទ (\(S\)) នោះការធានាឥតគិតថ្លៃត្រូវបានបាត់បង់ (\(V\))» (\(S \Rightarrow V\))។ អតិថិជនម្នាក់អះអាងថាការធានានៅតែមានសុពលភាព (\(\bar{V}\))។ តាមទ្រឹស្តីបទសំណើផ្ទុយពីសម្មតិកម្ម តើគេអាចសន្និដ្ឋានអ្វីបាន?', NULL, '["អតិថិជនបានបកតែមបិទឧបករណ៍", "ឧបករណ៍ខូចដោយសារធ្លាក់ទឹក", "ក្រុមហ៊ុនបដិសេធការធានា", "អតិថិជនមិនបានបកតែមបិទឧបករណ៍ឡើយ (\\(\\bar{S}\\))"]', 3, NULL, 3, 'mcq', 'តាមសំណើផ្ទុយពីសម្មតិកម្ម \((S \Rightarrow V) \iff (\bar{V} \Rightarrow \bar{S}\)) ដូច្នេះបើការធានាមិនទាន់បាត់បង់ នោះតែមមិនត្រូវបានបកឡើយ។', 'តក្កវិទ្យា', 'pisa', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10335, 'ធនាគារមួយកំណត់ថាពាក្យសម្ងាត់ត្រឹមត្រូវលុះត្រាតែមានប្រវែងយ៉ាងតិច 8 តួ (\(C\)) និងមានលេខកូដ (\(D\)) គឺ \(\text{Valid} = C \wedge D\)។ ប្រសិនបើពាក្យសម្ងាត់ត្រូវបានបដិសេធ (\(\overline{C \wedge D}\)) តើមានន័យថាយ៉ាងដូចម្តេច?', NULL, '["ពាក្យសម្ងាត់មានតិចជាង 8 តួ និងគ្មានលេខកូដ", "ពាក្យសម្ងាត់មានតិចជាង 8 តួ ឬគ្មានលេខកូដឡើយ (\\(\\bar{C} \\vee \\bar{D}\\))", "ពាក្យសម្ងាត់ត្រូវបានបញ្ចូលត្រឹមត្រូវ", "ពាក្យសម្ងាត់មានលើសពី 8 តួ"]', 1, NULL, 3, 'mcq', '\(\overline{C \wedge D} = \bar{C} \vee \bar{D}\) មានន័យថាខ្វះលក្ខខណ្ឌណាមួយ ឬខ្វះទាំងពីរ។', 'តក្កវិទ្យា', 'pisa', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10336, 'ក្នុងសៀគ្វីតក្កវិទ្យាឌីជីថល ទិន្នផលចេញគឺ \(Y = (A \wedge B) \vee \bar{C}\)។ បើកុងតាក់ \(A = 1\) (ON), \(B = 0\) (OFF) និង \(C = 0\) (OFF) តើទិន្នផល \(Y\) មានតម្លៃស្មើនឹងប៉ុន្មាន?', NULL, '["\\(-1\\)", "គ្មានចរន្តអគ្គិសនី", "\\(1\\) (ដំណើរការ / ភ្លើងភ្លឺ)", "\\(0\\) (មិនដំណើរការ / ភ្លើងរលត់)"]', 2, NULL, 3, 'mcq', '\(A \wedge B = 1 \wedge 0 = 0\) ហើយ \(\bar{C} = \bar{0} = 1\) នាំឱ្យ \(Y = 0 \vee 1 = 1\)។', 'តក្កវិទ្យា', 'pisa', 1, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10337, 'ពិនិត្យអំណះអំណាងខាងក្រោម ៖
ក. «2025 ជាចំនួនគត់សេស»
ខ. «តើថ្ងៃនេះក្តៅដែរឬទេ?»
ចូរប្រាប់ថាតើអំណះអំណាងនីមួយៗជាសំណើឬទេ? បើជាសំណើ ចូរបញ្ជាក់តម្លៃភាពពិតរបស់វា។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ជាសំណើ ព្រោះអាចសម្រេចបានថាពិតច្បាស់លាស់ (2 ពិន្ទុ)
តម្លៃភាពពិតនៃ ក គឺ ត. = 1 ព្រោះ 2025 មានលេខចុងក្រោយ 5 ជាចំនួនសេស (1 ពិន្ទុ)
ខ. មិនមែនជាសំណើទេ ព្រោះជាប្រយោគសំនួរ មិនអាចសម្រេចថាពិតឬមិនពិតបានឡើយ (2 ពិន្ទុ)', 'តក្កវិទ្យា', 'easy', 0, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10338, 'សង់តារាងភាពពិតនៃកន្សោមសំណើ \(p \vee (q \wedge \bar{p})\) ចំពោះគ្រប់ករណីនៃសំណើ \(p\) និង \(q\)។', NULL, '[]', 0, NULL, 5, 'writing', 'រៀបចំជួរឈរនៃ p, q និងគណនា \bar{p} ត្រឹមត្រូវ (1 ពិន្ទុ)
គណនាជួរឈរ q \wedge \bar{p} តាមគ្រប់ករណី [0, 0, 1, 0] (2 ពិន្ទុ)
គណនាកន្សោមចុងក្រោយ p \vee (q \wedge \bar{p}) ទទួលបាន [1, 1, 1, 0] (2 ពិន្ទុ)', 'តក្កវិទ្យា', 'medium', 0, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10339, 'សរសេររូបមន្តច្បាប់ដឺម៉កហ្កង់ (De Morgan Laws) ទាំងពីរ និងសង់តារាងភាពពិតផ្ទៀងផ្ទាត់សមភាព \(\overline{p \vee q} = \bar{p} \wedge \bar{q}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្ត: \overline{p \vee q} = \bar{p} \wedge \bar{q} និង \overline{p \wedge q} = \bar{p} \vee \bar{q} (2 ពិន្ទុ)
សង់តារាងភាពពិតបង្ហាញជួរឈរ \overline{p \vee q} មានតម្លៃ [0, 0, 0, 1] (2 ពិន្ទុ)
បង្ហាញជួរឈរ \bar{p} \wedge \bar{q} មានតម្លៃ [0, 0, 0, 1] ដូចគ្នាគ្រប់ករណី នាំឱ្យសមមូលគ្នា (1 ពិន្ទុ)', 'តក្កវិទ្យា', 'medium', 0, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10340, 'ដោយប្រើសម្រាយបញ្ជាក់ដោយផ្ទាល់ ចូរបង្ហាញថាបើ \(x\) និង \(y\) ជាចំនួនគត់សេស នោះផលគុណ \(xy\) ក៏ជាចំនួនគត់សេសដែរ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង x = 2n+1 និង y = 2m+1 ដែល n, m ជាចំនួនគត់ (1 ពិន្ទុ)
គណនាផលគុណ xy = (2n+1)(2m+1) = 4nm + 2n + 2m + 1 (2 ពិន្ទុ)
ដាក់ជាផលគុណកត្តា: xy = 2(2nm + n + m) + 1 = 2k + 1 ដែល k = 2nm+n+m ជាចំនួនគត់ (1 ពិន្ទុ)
សន្និដ្ឋានថា xy ជាចំនួនគត់សេស (ពិត) (1 ពិន្ទុ)', 'តក្កវិទ្យា', 'medium', 0, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10341, 'គេមានសំណើ «បើ \(x > 2\) នោះ \(x^2 > 4\)»។ ចូរសរសេរ ៖
ក. សំណើច្រាស (Converse)
ខ. សំណើផ្ទុយ (Inverse)
គ. សំណើផ្ទុយពីសម្មតិកម្ម (Contrapositive)', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់សំណើដើម p: x > 2 និង q: x^2 > 4 (1 ពិន្ទុ)
ក. សំណើច្រាស (q \Rightarrow p): «បើ x^2 > 4 នោះ x > 2» (1 ពិន្ទុ)
ខ. សំណើផ្ទុយ (\bar{p} \Rightarrow \bar{q}): «បើ x \le 2 នោះ x^2 \le 4» (1 ពិន្ទុ)
គ. សំណើផ្ទុយពីសម្មតិកម្ម (\bar{q} \Rightarrow \bar{p}): «បើ x^2 \le 4 នោះ x \le 2» (2 ពិន្ទុ)', 'តក្កវិទ្យា', 'medium', 0, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10342, 'ដោយប្រើសម្រាយបញ្ជាក់តាមសំណើផ្ទុយពីសម្មតិកម្ម ចូរបង្ហាញថាបើ \(n^2\) ជាចំនួនគត់គូ នោះ \(n\) ជាចំនួនគត់គូ។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរសំណើផ្ទុយពីសម្មតិកម្ម: «បើ n ជាចំនួនគត់សេស នោះ n^2 ជាចំនួនគត់សេស» (1 ពិន្ទុ)
តាង n = 2k+1 (k ជាចំនួនគត់) គណនា n^2 = (2k+1)^2 = 4k^2+4k+1 (2 ពិន្ទុ)
សរសេរ n^2 = 2(2k^2+2k)+1 = 2m+1 បញ្ជាក់ថា n^2 ជាចំនួនគត់សេស (ពិត) (1 ពិន្ទុ)
សន្និដ្ឋានថាសំណើផ្ទុយពីសម្មតិកម្មពិត នាំឱ្យសំណើដើម «បើ n^2 គូ នោះ n គូ» ពិត (1 ពិន្ទុ)', 'តក្កវិទ្យា', 'hard', 0, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10343, 'ដោយប្រើសម្រាយបញ្ជាក់តាមសំណើផ្ទុយពីការពិត ចូរបង្ហាញថា \(\sqrt{3}\) គឺជាចំនួនអសនិទាន។', NULL, '[]', 0, NULL, 5, 'writing', 'ឧបមាផ្ទុយថា \sqrt{3} ជាចំនួនសនិទាន នោះ \sqrt{3} = a/b ដែល a, b ជាចំនួនគត់បឋមរវាងគ្នា GCD(a,b)=1 (1 ពិន្ទុ)
លើកជាការេ 3 = a^2/b^2 \implies a^2 = 3b^2 នាំឱ្យ a^2 ចែកដាច់នឹង 3 នាំឱ្យ a ចែកដាច់នឹង 3 (a = 3k) (1 ពិន្ទុ)
ជំនួស a = 3k ចូល: 9k^2 = 3b^2 \implies b^2 = 3k^2 នាំឱ្យ b ចែកដាច់នឹង 3 ដែរ (2 ពិន្ទុ)
ទាញបាន a និង b មាន 3 ជាតួចែករួម ផ្ទុយពី GCD(a,b)=1 នាំឱ្យការឧបមាមិនពិត ដូច្នេះ \sqrt{3} ជាចំនួនអសនិទាន (1 ពិន្ទុ)', 'តក្កវិទ្យា', 'hard', 0, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10344, 'ចំពោះចំនួនពិត \(x, y\) ចូរបង្ហាញថា \(x^2 + y^2 = 0\) លុះត្រាតែ \(x = 0\) និង \(y = 0\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បង្ហាញ q \Rightarrow p: បើ x = 0 និង y = 0 នោះ 0^2 + 0^2 = 0 ពិត (1 ពិន្ទុ)
បង្ហាញ p \Rightarrow q: ដោយ x, y ជាចំនួនពិត គេបាន x^2 \ge 0 និង y^2 \ge 0 ជានិច្ច (2 ពិន្ទុ)
ផលបូកពីរចំនួនមិនអវិជ្ជមានស្មើ 0 លុះត្រាតែតួនីមួយៗស្មើ 0 គឺ x^2 = 0 \implies x=0 និង y^2 = 0 \implies y=0 (1 ពិន្ទុ)
សន្និដ្ឋានថា (x^2+y^2=0) \Leftrightarrow (x=0 \text{ និង } y=0) ពិតជាលក្ខខណ្ឌចាំបាច់និងគ្រប់គ្រាន់ (1 ពិន្ទុ)', 'តក្កវិទ្យា', 'hard', 0, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10345, 'ដោយប្រើសម្រាយបញ្ជាក់តាមសំណើផ្ទុយពីសម្មតិកម្ម ចូរបង្ហាញថាបើ \(x(x-2) < 0\) នោះ \(0 < x < 2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់សំណើផ្ទុយពីសម្មតិកម្ម: «បើ x \le 0 ឬ x \ge 2 នោះ x(x-2) \ge 0» (1 ពិន្ទុ)
