ករណីទី ២: បើ x \ge 2 នោះ x > 0 និង x-2 \ge 0 នាំឱ្យផលគុណ x(x-2) \ge 0 (ផលគុណពីរចំនួនវិជ្ជមាន) (1.5 ពិន្ទុ)
សន្និដ្ឋានថាសំណើផ្ទុយពីសម្មតិកម្មពិតគ្រប់ករណី នាំឱ្យសំណើដើមពិត (1 ពិន្ទុ)', 'តក្កវិទ្យា', 'hard', 0, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10346, 'ប្រព័ន្ធសុវត្ថិភាពផ្ទះឆ្លាតវៃមួយនឹងបន្លឺសំឡេងប្រកាសអាសន្ន (Alert) កាលណា៖ «សីតុណ្ហភាពឡើងលើសពី \(50^\circ\text{C}\) (\(T\)) ឬមានផ្សែង (\(S\))»។
ក. សរសេរសំណើតក្កវិទ្យានៃ Alert។
ខ. សរសេរសំណើបដិសេធ \overline{Alert} តាមច្បាប់ De Morgan និងបកស្រាយអត្ថន័យ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. សរសេរសំណើតក្កវិទ្យា Alert = T \vee S (1 ពិន្ទុ)
ខ. អនុវត្តច្បាប់ដឺម៉កហ្កង់: \overline{\text{Alert}} = \overline{T \vee S} = \bar{T} \wedge \bar{S} (2 ពិន្ទុ)
បកស្រាយ: ផ្ទះមានសុវត្ថិភាព (គ្មានអាសន្ន) លុះត្រាតែសីតុណ្ហភាពមិនលើសពី 50°C និងគ្មានផ្សែងព្រមគ្នា (2 ពិន្ទុ)', 'តក្កវិទ្យា', 'pisa', 0, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10347, 'ធនាគារមួយអនុម័តកម្ចីទិញផ្ទះ (Approved) លុះត្រាតែអតិថិជនមាន «ប្រាក់ចំណូលប្រចាំខែយ៉ាងតិច \(1\,000\) ដុល្លារ (\(I\)) និងពិន្ទុឥណទានយ៉ាងតិច 700 (\(C\))»។
ក. សរសេរសំណើតក្កវិទ្យានៃ Approved។
ខ. សរសេរសំណើបដិសេធកម្ចី \overline{Approved} និងបកស្រាយលក្ខខណ្ឌដែលអតិថិជនត្រូវធ្លាក់កម្ចី។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. សរសេរសំណើតក្កវិទ្យា Approved = I \wedge C (1 ពិន្ទុ)
ខ. សរសេរសំណើបដិសេធ: \overline{\text{Approved}} = \overline{I \wedge C} = \bar{I} \vee \bar{C} (2 ពិន្ទុ)
បកស្រាយ: អតិថិជននឹងត្រូវធ្លាក់កម្ចី បើប្រាក់ចំណូលទាបជាង $1,000 ឬពិន្ទុឥណទានទាបជាង 700 (ឬខ្វះទាំងពីរ) (2 ពិន្ទុ)', 'តក្កវិទ្យា', 'pisa', 0, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10348, 'ប្រព័ន្ធចាក់សោឌីជីថលសុវត្ថិភាពមួយនឹងបើក (\(U = 1\)) កាលណា \(A \wedge (\bar{B} \vee C) = 1\)។
ក. ចូរបង្កើតតារាងភាពពិតសម្រាប់កន្សោម \(U = A \wedge (\bar{B} \vee C)\)។
ខ. រកបន្សំនៃកុងតាក់ \((A, B, C)\) ណាខ្លះដែលអាចបើកទូសុវត្ថិភាពនេះបាន។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. សង់តារាងភាពពិតសម្រាប់គ្រប់ករណីទាំង 8 នៃ A, B, C (2 ពិន្ទុ)
គណនាជួរឈរ \bar{B} \vee C និងទាញរកតម្លៃ U = A \wedge (\bar{B} \vee C) (2 ពិន្ទុ)
ខ. ទូសុវត្ថិភាពបើក (U=1) ពេល (A,B,C) មានតម្លៃ (1,0,0), (1,0,1), (1,1,1) (1 ពិន្ទុ)', 'តក្កវិទ្យា', 'pisa', 0, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10349, 'រោងចក្រផលិតបន្ទះសូឡាមួយកំណត់ថាបន្ទះត្រូវបានចាត់ទុកថា «ខូច» (\(D\)) កាលណា «ប្រសិទ្ធភាពទាបជាង \(20\%\) (\(E\)) ឬមានស្នាមប្រេះ (\(M\))» គឺ \(D = E \vee M\)។
ក. សរសេរសំណើតាងបន្ទះជាប់ស្តង់ដារគុណភាពល្អ (\(P = \bar{D}\))។
ខ. វិស្វករពិនិត្យបន្ទះមួយឃើញមានប្រសិទ្ធភាព \(22\%\) ប៉ុន្តែមានស្នាមប្រេះស្រាំ។ តើបន្ទះនេះជាប់ស្តង់ដារឬទេ? ពន្យល់តាមតក្កវិទ្យា។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បន្ទះជាប់គុណភាពល្អ: P = \bar{D} = \overline{E \vee M} = \bar{E} \wedge \bar{M} (2 ពិន្ទុ)
ខ. ប្រសិទ្ធភាព 22% \ge 20% នាំឱ្យ E = 0 (\bar{E} = 1 ពិត) (1 ពិន្ទុ)
ដោយមានស្នាមប្រេះ នាំឱ្យ M = 1 (\bar{M} = 0 មិនពិត) (1 ពិន្ទុ)
តម្លៃភាពពិត P = 1 \wedge 0 = 0 ដូច្នេះបន្ទះនេះមិនជាប់ស្តង់ដារគុណភាពឡើយ (ត្រូវបានច្រានចោល) (1 ពិន្ទុ)', 'តក្កវិទ្យា', 'pisa', 0, '10', 'តក្កវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10350, 'ម៉ាស៊ីនមេ (Server) មួយអនុញ្ញាតឱ្យចូលប្រើប្រាស់ (\(A\)) ក្នុងលក្ខខណ្ឌ ៖ «អ្នកប្រើជា Admin (\(U\)) ឬ (មាន Token សុពលភាព (\(T\)) និង Server មិនរវល់ (\(\bar{B}\)))» គឺ \(A = U \vee (T \wedge \bar{B})\)។
ក. បើអ្នកប្រើជាបុគ្គលិកធម្មតា (\(U = 0\)) មាន Token ត្រឹមត្រូវ (\(T = 1\)) ប៉ុន្តែ Server កំពុងរវល់ខ្លាំង (\(B = 1\))។ តើគាត់អាចចូល Server បានទេ?
ខ. បង្ហាញការគណនាតម្លៃភាពពិតនៃ \(A\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. កំណត់តម្លៃភាពពិតនៃធាតុនីមួយៗ: U = 0, T = 1, B = 1 \implies \bar{B} = 0 (1 ពិន្ទុ)
ខ. គណនា T \wedge \bar{B} = 1 \wedge 0 = 0 (2 ពិន្ទុ)
គណនា A = U \vee (T \wedge \bar{B}) = 0 \vee 0 = 0 (1 ពិន្ទុ)
សន្និដ្ឋាន: ដោយ A = 0 នោះគាត់មិនអាចចូលប្រើប្រាស់ Server បានឡើយ (1 ពិន្ទុ)', 'តក្កវិទ្យា', 'pisa', 0, '10', 'តក្កវិទ្យា', NULL, 0);
